-- PostgreSQL design draft. Review in a disposable database before migration.
-- Server must set app.company_id and app.actor_id from authenticated session,
-- never from request JSON. Demo HTML is not connected to this schema.
BEGIN;
CREATE SCHEMA IF NOT EXISTS lona;
SET search_path=lona,public;
CREATE TABLE company(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text NOT NULL UNIQUE,name text NOT NULL);
CREATE TABLE branch(company_id uuid NOT NULL REFERENCES company,id uuid NOT NULL DEFAULT gen_random_uuid(),code text NOT NULL,name text NOT NULL,accounting_mode text NOT NULL CHECK(accounting_mode IN('centralized','dependent','independent')),PRIMARY KEY(company_id,id),UNIQUE(company_id,code));
CREATE TABLE kitchen(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),branch_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,PRIMARY KEY(company_id,id),UNIQUE(company_id,code),FOREIGN KEY(company_id,branch_id) REFERENCES branch(company_id,id));
CREATE TABLE warehouse(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),branch_id uuid NOT NULL,code text NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN('central','branch','transit','production','quarantine')),active boolean NOT NULL DEFAULT true,PRIMARY KEY(company_id,id),UNIQUE(company_id,code),FOREIGN KEY(company_id,branch_id) REFERENCES branch(company_id,id));
CREATE TABLE kitchen_warehouse(company_id uuid NOT NULL,kitchen_id uuid NOT NULL,warehouse_id uuid NOT NULL,priority integer NOT NULL CHECK(priority>0),PRIMARY KEY(company_id,kitchen_id,warehouse_id),FOREIGN KEY(company_id,kitchen_id) REFERENCES kitchen(company_id,id),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouse(company_id,id));
CREATE TABLE app_user(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),username text NOT NULL UNIQUE,identity_subject text NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true);
CREATE TABLE warehouse_grant(company_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES app_user,warehouse_id uuid NOT NULL,permission text NOT NULL CHECK(permission IN('view','request','approve','dispatch','receive','issue','count','value')),PRIMARY KEY(company_id,user_id,warehouse_id,permission),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouse(company_id,id));
CREATE TABLE unit(code text PRIMARY KEY,dimension text NOT NULL CHECK(dimension IN('mass','volume','count')));
CREATE TABLE item(company_id uuid NOT NULL REFERENCES company,id uuid NOT NULL DEFAULT gen_random_uuid(),code text NOT NULL,name text NOT NULL,category text NOT NULL,base_unit text NOT NULL REFERENCES unit,lot_tracked boolean NOT NULL DEFAULT false,active boolean NOT NULL DEFAULT true,PRIMARY KEY(company_id,id),UNIQUE(company_id,code));
CREATE TABLE item_conversion(company_id uuid NOT NULL,item_id uuid NOT NULL,unit text NOT NULL REFERENCES unit,factor numeric(20,9) NOT NULL CHECK(factor>0),approved_by uuid NOT NULL REFERENCES app_user,PRIMARY KEY(company_id,item_id,unit),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id));
CREATE TABLE package_spec(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),item_id uuid NOT NULL,name text NOT NULL,base_qty numeric(20,6) NOT NULL CHECK(base_qty>0),valid_from date NOT NULL,valid_to date,CHECK(valid_to IS NULL OR valid_to>=valid_from),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id));
CREATE TABLE lot(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),item_id uuid NOT NULL,lot_code text NOT NULL,expires_on date,PRIMARY KEY(company_id,id),UNIQUE(company_id,item_id,id),UNIQUE(company_id,item_id,lot_code),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id));
-- One SKU may have independent balances in multiple physical warehouses.
CREATE TABLE stock_balance(company_id uuid NOT NULL,warehouse_id uuid NOT NULL,item_id uuid NOT NULL,qty numeric(20,6) NOT NULL DEFAULT 0 CHECK(qty>=0),version bigint NOT NULL DEFAULT 1,PRIMARY KEY(company_id,warehouse_id,item_id),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouse(company_id,id),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id));
CREATE TABLE accounting_period(company_id uuid NOT NULL REFERENCES company,from_date date NOT NULL,to_date date NOT NULL,closed boolean NOT NULL DEFAULT false,closed_by uuid REFERENCES app_user,PRIMARY KEY(company_id,from_date),CHECK(to_date>=from_date));
CREATE TABLE stock_document(company_id uuid NOT NULL REFERENCES company,id uuid NOT NULL DEFAULT gen_random_uuid(),number text NOT NULL,fiscal_year integer NOT NULL,type text NOT NULL CHECK(type IN('receipt','transfer','production_issue','return','adjustment')),source_warehouse uuid,target_warehouse uuid,kitchen_id uuid,document_date date NOT NULL,posting_date date,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','submitted','approved','in_transit','partial','posted','cancelled')),version bigint NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES app_user,approved_by uuid REFERENCES app_user,approved_at timestamptz,reverses_id uuid,PRIMARY KEY(company_id,id),UNIQUE(company_id,fiscal_year,type,number),CHECK(source_warehouse IS DISTINCT FROM target_warehouse),FOREIGN KEY(company_id,source_warehouse) REFERENCES warehouse(company_id,id),FOREIGN KEY(company_id,target_warehouse) REFERENCES warehouse(company_id,id),FOREIGN KEY(company_id,kitchen_id) REFERENCES kitchen(company_id,id),FOREIGN KEY(company_id,reverses_id) REFERENCES stock_document(company_id,id),CHECK(status NOT IN('approved','in_transit','partial','posted') OR approved_by IS NOT NULL));
CREATE TABLE stock_document_line(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),document_id uuid NOT NULL,line_no integer NOT NULL CHECK(line_no>0),item_id uuid NOT NULL,lot_id uuid,requested numeric(20,6) NOT NULL CHECK(requested>0),dispatched numeric(20,6) NOT NULL DEFAULT 0,received numeric(20,6) NOT NULL DEFAULT 0,base_unit text NOT NULL REFERENCES unit,unit_cost_snapshot numeric(20,6) CHECK(unit_cost_snapshot>=0),PRIMARY KEY(company_id,id),UNIQUE(company_id,document_id,line_no),FOREIGN KEY(company_id,document_id) REFERENCES stock_document(company_id,id),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id),FOREIGN KEY(company_id,item_id,lot_id) REFERENCES lot(company_id,item_id,id),CHECK(received>=0 AND dispatched>=received AND requested>=dispatched));
CREATE TABLE reservation(company_id uuid NOT NULL,line_id uuid NOT NULL,warehouse_id uuid NOT NULL,item_id uuid NOT NULL,qty numeric(20,6) NOT NULL CHECK(qty>0),active boolean NOT NULL DEFAULT true,PRIMARY KEY(company_id,line_id),FOREIGN KEY(company_id,line_id) REFERENCES stock_document_line(company_id,id),FOREIGN KEY(company_id,warehouse_id,item_id) REFERENCES stock_balance(company_id,warehouse_id,item_id));
CREATE TABLE posting_batch(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),document_id uuid NOT NULL,phase text NOT NULL CHECK(phase IN('dispatch','receive','issue','receipt','reverse','adjust')),request_id uuid NOT NULL,payload_hash text NOT NULL,actor_id uuid NOT NULL REFERENCES app_user,posted_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,id),UNIQUE(company_id,request_id),FOREIGN KEY(company_id,document_id) REFERENCES stock_document(company_id,id));
CREATE TABLE stock_entry(company_id uuid NOT NULL,id bigint GENERATED ALWAYS AS IDENTITY,batch_id uuid NOT NULL,document_line_id uuid NOT NULL,warehouse_id uuid NOT NULL,item_id uuid NOT NULL,quantity numeric(20,6) NOT NULL CHECK(quantity<>0),value_amount numeric(20,6),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,batch_id) REFERENCES posting_batch(company_id,id),FOREIGN KEY(company_id,document_line_id) REFERENCES stock_document_line(company_id,id),FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouse(company_id,id),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id));
CREATE FUNCTION prevent_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Posted ledger is append-only; create reversal'; END $$;
CREATE TRIGGER immutable_stock_entry BEFORE UPDATE OR DELETE ON stock_entry FOR EACH ROW EXECUTE FUNCTION prevent_ledger_mutation();
CREATE TABLE dish(company_id uuid NOT NULL REFERENCES company,id uuid NOT NULL DEFAULT gen_random_uuid(),code text NOT NULL,name text NOT NULL,PRIMARY KEY(company_id,id),UNIQUE(company_id,code));
CREATE TABLE recipe_version(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),dish_id uuid NOT NULL,version integer NOT NULL CHECK(version>0),yield_qty numeric(20,6) NOT NULL CHECK(yield_qty>0),yield_unit text NOT NULL,valid_from date NOT NULL,status text NOT NULL CHECK(status IN('draft','approved','retired')),approved_by uuid REFERENCES app_user,PRIMARY KEY(company_id,id),UNIQUE(company_id,dish_id,version),FOREIGN KEY(company_id,dish_id) REFERENCES dish(company_id,id),CHECK(status<>'approved' OR approved_by IS NOT NULL));
CREATE TABLE recipe_line(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),recipe_id uuid NOT NULL,item_id uuid,child_recipe_id uuid,quantity numeric(20,6) NOT NULL CHECK(quantity>0),unit text NOT NULL REFERENCES unit,basis text NOT NULL CHECK(basis IN('raw','cooked')),yield_rate numeric(12,6) CHECK(yield_rate>0),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,recipe_id) REFERENCES recipe_version(company_id,id),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id),FOREIGN KEY(company_id,child_recipe_id) REFERENCES recipe_version(company_id,id),CHECK((item_id IS NOT NULL)::int+(child_recipe_id IS NOT NULL)::int=1),CHECK(child_recipe_id IS DISTINCT FROM recipe_id),CHECK(basis<>'cooked' OR yield_rate IS NOT NULL));
CREATE TABLE meal_plan(company_id uuid NOT NULL,kitchen_id uuid NOT NULL,service_date date NOT NULL,meal text NOT NULL CHECK(meal IN('breakfast','lunch','afternoon','dinner')),normal integer NOT NULL CHECK(normal>=0),vegetarian integer NOT NULL DEFAULT 0 CHECK(vegetarian>=0),replacement integer NOT NULL DEFAULT 0 CHECK(replacement>=0),replacement_included boolean NOT NULL DEFAULT true,status text NOT NULL CHECK(status IN('draft','approved','locked')),revision bigint NOT NULL DEFAULT 1,PRIMARY KEY(company_id,kitchen_id,service_date,meal),FOREIGN KEY(company_id,kitchen_id) REFERENCES kitchen(company_id,id),CHECK(NOT replacement_included OR replacement<=normal));
CREATE TABLE menu_line(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),kitchen_id uuid NOT NULL,service_date date NOT NULL,meal text NOT NULL,slot text NOT NULL,recipe_id uuid NOT NULL,portion_scope text NOT NULL CHECK(portion_scope IN('main','normal','shared','vegetarian','replacement','fixed')),fixed_portions integer CHECK(fixed_portions>=0),PRIMARY KEY(company_id,id),UNIQUE(company_id,kitchen_id,service_date,meal,slot),FOREIGN KEY(company_id,kitchen_id,service_date,meal) REFERENCES meal_plan(company_id,kitchen_id,service_date,meal),FOREIGN KEY(company_id,recipe_id) REFERENCES recipe_version(company_id,id),CHECK(portion_scope<>'fixed' OR fixed_portions IS NOT NULL));
CREATE TABLE import_batch(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),file_name text NOT NULL,sha256 text NOT NULL,parser_version text NOT NULL,status text NOT NULL CHECK(status IN('staged','validated','imported','rejected')),created_by uuid NOT NULL REFERENCES app_user,PRIMARY KEY(company_id,id),UNIQUE(company_id,sha256,parser_version));
CREATE TABLE import_row(company_id uuid NOT NULL,batch_id uuid NOT NULL,sheet text NOT NULL,row_no integer NOT NULL CHECK(row_no>0),raw jsonb NOT NULL,mapped jsonb,errors jsonb NOT NULL DEFAULT '[]',PRIMARY KEY(company_id,batch_id,sheet,row_no),FOREIGN KEY(company_id,batch_id) REFERENCES import_batch(company_id,id));
CREATE TABLE planning_run(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),kitchen_id uuid NOT NULL,business_date date NOT NULL,job text NOT NULL,input_hash text NOT NULL,revision integer NOT NULL CHECK(revision>0),status text NOT NULL CHECK(status IN('running','ready','blocked','failed','superseded')),started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,PRIMARY KEY(company_id,id),UNIQUE(company_id,kitchen_id,business_date,job,input_hash),FOREIGN KEY(company_id,kitchen_id) REFERENCES kitchen(company_id,id));
CREATE TABLE planning_snapshot(company_id uuid NOT NULL,run_id uuid NOT NULL,horizon text NOT NULL CHECK(horizon IN('D1','D2','D3','WEEK','MONTH')),from_date date NOT NULL,to_date date NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(company_id,run_id,horizon),FOREIGN KEY(company_id,run_id) REFERENCES planning_run(company_id,id),CHECK(to_date>=from_date));
CREATE TABLE allocation(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),run_id uuid NOT NULL,kitchen_id uuid NOT NULL,need_date date NOT NULL,item_id uuid NOT NULL,source_document_line uuid,quantity numeric(20,6) NOT NULL CHECK(quantity>0),status text NOT NULL CHECK(status IN('proposed','approved','fulfilled','cancelled')),PRIMARY KEY(company_id,id),FOREIGN KEY(company_id,run_id) REFERENCES planning_run(company_id,id),FOREIGN KEY(company_id,kitchen_id) REFERENCES kitchen(company_id,id),FOREIGN KEY(company_id,item_id) REFERENCES item(company_id,id),FOREIGN KEY(company_id,source_document_line) REFERENCES stock_document_line(company_id,id));
CREATE TABLE accounting_outbox(company_id uuid NOT NULL,id uuid NOT NULL DEFAULT gen_random_uuid(),batch_id uuid NOT NULL,target_system text NOT NULL,external_id text,status text NOT NULL CHECK(status IN('pending','sent','acknowledged','failed')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0),payload jsonb NOT NULL,last_error text,PRIMARY KEY(company_id,id),UNIQUE(company_id,batch_id,target_system),FOREIGN KEY(company_id,batch_id) REFERENCES posting_batch(company_id,id));
CREATE TABLE audit_event(company_id uuid NOT NULL REFERENCES company,id bigint GENERATED ALWAYS AS IDENTITY,actor_id uuid NOT NULL REFERENCES app_user,at timestamptz NOT NULL DEFAULT now(),entity text NOT NULL,entity_id uuid NOT NULL,action text NOT NULL,before_data jsonb,after_data jsonb,PRIMARY KEY(company_id,id));
CREATE INDEX meal_plan_date_idx ON meal_plan(company_id,kitchen_id,service_date);
CREATE INDEX document_queue_idx ON stock_document(company_id,status,document_date);
CREATE INDEX entry_warehouse_item_idx ON stock_entry(company_id,warehouse_id,item_id,id);
CREATE INDEX reservations_active_idx ON reservation(company_id,warehouse_id,item_id) WHERE active;
CREATE INDEX outbox_pending_idx ON accounting_outbox(status) WHERE status IN('pending','failed');
-- Company isolation is a second boundary. Per-warehouse grants must also be checked
-- at service/queries; company RLS alone does NOT implement warehouse isolation.
DO $$ DECLARE t record; BEGIN FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='lona' AND tablename NOT IN('company','app_user','unit') LOOP EXECUTE format('ALTER TABLE lona.%I ENABLE ROW LEVEL SECURITY',t.tablename); EXECUTE format('ALTER TABLE lona.%I FORCE ROW LEVEL SECURITY',t.tablename); EXECUTE format('CREATE POLICY company_boundary ON lona.%I USING (company_id = nullif(current_setting(''app.company_id'',true),'''')::uuid) WITH CHECK (company_id = nullif(current_setting(''app.company_id'',true),'''')::uuid)',t.tablename); END LOOP; END $$;
COMMIT;
-- Required service transactions (not implemented by DDL alone):
-- 1) Verify session and both warehouse grants; check company and open period.
-- 2) Lock stock_document FOR UPDATE; compare expected version; lock balances
--    in stable warehouse/item order; include all active reservations.
-- 3) Insert posting_batch with request_id + payload_hash; a repeated id with
--    different payload is rejected, same id returns original receipt.
-- 4) Dispatch: debit source qty, credit transit qty, append two entries,
--    release reservation, update dispatched/status in the SAME transaction.
-- 5) Receive: bound quantity by THIS line's dispatched - received; debit transit,
--    credit destination, append entries, update received/status atomically.
-- 6) Append accounting_outbox in same transaction. External accounting retry
--    uses batch_id; it must not post inventory again.
-- 7) Validate transfer legs sum to zero per item in batch, immutable approved
--    recipe/menu snapshots, and lot/expiry allocations in service or deferred triggers.
-- DDL intentionally does not claim these transaction rules are implemented.
